Brief: Tell me how MangoDB's indexes work and when a query uses them. — about addToIndexes

1. * Called after insert operations.
2. * Waits for any in-progress build to complete before updating.
3. * @param doc - The document that was inserted
4. async addToIndexes<T extends Document>(doc: T): Promise<void> {
5. // Wait for any in-progress build to complete
6. if (this.buildInProgress) {
7. await this.buildInProgress;
8. // If indexes were never built (no queries yet), skip the update.
9. // The document is already in the data file, so the next build will include it.
10. if (!this.indexesBuilt) return;
11. const docId = this.getDocIdString(doc);
12. if (docId === null) return;

